// The sample schema used by App.jsx. Do not edit this file (the tests of App rely on it).
//
// A schema is plain data (what you could receive as JSON): an array of field objects.
// A field has these properties:
//
//   name            unique key. It is also the key in the submitted values.
//   label           the text of the <label>
//   type            'text' | 'number' | 'select' | 'checkbox'
//   required        (optional) true means: must be filled in (or checked)
//   min, max        (optional, number fields only)
//   minLength       (optional, text fields only)
//   pattern         (optional, text fields only) a regular expression written as a string
//   patternMessage  (optional) the error message when the pattern does not match
//   options         (select fields only) an array of strings
//   showIf          (optional) { field: 'otherName', equals: someValue }

export const sampleSchema = [
  {
    name: 'fullName',
    label: 'Full name',
    type: 'text',
    required: true,
    minLength: 2,
  },
  {
    name: 'email',
    label: 'Email',
    type: 'text',
    required: true,
    pattern: '^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$',
    patternMessage: 'Enter a valid email address',
  },
  {
    name: 'age',
    label: 'Age',
    type: 'number',
    required: true,
    min: 18,
    max: 120,
  },
  {
    name: 'role',
    label: 'Role',
    type: 'select',
    required: true,
    options: ['Developer', 'Designer', 'Manager'],
  },
  {
    name: 'teamSize',
    label: 'Team size',
    type: 'number',
    min: 1,
    showIf: { field: 'role', equals: 'Manager' },
  },
  {
    name: 'hasCompany',
    label: 'I work for a company',
    type: 'checkbox',
  },
  {
    name: 'company',
    label: 'Company name',
    type: 'text',
    required: true,
    showIf: { field: 'hasCompany', equals: true },
  },
  {
    name: 'terms',
    label: 'I accept the terms',
    type: 'checkbox',
    required: true,
  },
]
